-- Daily challenges for 2026-10-03: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-03

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('saying-what-you-feel', 'Saying What You Feel', 'For anyone who keeps feelings to themselves until they spill over, or never quite finds the words. Each day is one small practice in noticing a feeling, naming it, and saying it out loud to someone in a way that feels safe.', 'Communication', 365, array['Emotion Regulation', 'Communication', 'Relationships']::text[], 1, '2026-10-03T17:00:00+00:00'::timestamptz),
  ('a-gentler-commute', 'A Gentler Commute', 'For anyone whose trip to work, school or errands leaves them tense before the day has started. Each day is one small way to make time on the road, the train, the bus or the sidewalk calmer and a little more your own.', 'Stress', 365, array['Stress', 'Mindfulness']::text[], 1, '2026-10-03T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('saying-what-you-feel', 'a-gentler-commute');

